window.LEXBOOK={"label": "ch1", "words": {"indigenous": {"term": "indigenous", "zh": "本土的", "pos": "形", "src": "", "ex": {"en": "Culturally, indigenous traditions, such as Confucianism and Daoism, have profoundly influenced the philosophy, literature, and arts of the Chinese people.", "zh": "从文化上看，儒家、道家等本土传统，连同佛教等外来宗教，数百年来深刻影响了中国人民的哲学、文学与艺术。"}, "key": "indigenous", "aud": false, "hits": []}, "philosophy": {"term": "philosophy", "zh": "哲学", "pos": "名", "src": "", "ex": {"en": "Chinese philosophy is one of the three major philosophical traditions in the world.", "zh": "中国哲学是世界上三大哲学传统之一，另外两大分别是西方哲学和印度哲学。"}, "key": "philosophy", "aud": false, "hits": []}, "school of thought": {"term": "school of thought", "zh": "学派", "pos": "名", "src": "", "ex": {"en": "Chinese philosophy is the collective designation for various schools of thought.", "zh": "中国哲学是对各种思想学派的总体称谓。"}, "key": "school_of_thought", "aud": false, "hits": []}, "the contention of a hundred schools of thought": {"term": "the contention of a hundred schools of thought", "zh": "百家争鸣", "pos": "短语", "src": "", "ex": {"en": "Chinese philosophy flourished with the emergence of \"the contention of a hundred schools of thought\".", "zh": "中国哲学随着\"百家争鸣\"局面的出现而兴盛起来。"}, "key": "the_contention_of_a_hundred_schools_of_thought", "aud": true, "hits": []}, "emerge": {"term": "emerge", "zh": "出现；相继兴起", "pos": "动", "src": "", "ex": {"en": "During this time, various schools of thought, such as Confucianism, Legalism, Daoism, and Mohism, emerged.", "zh": "这一时期，儒家、法家、道家和墨家等学派相继出现。"}, "key": "emerge", "aud": false, "hits": []}, "vigorously": {"term": "vigorously", "zh": "积极地；充满活力地", "pos": "副", "src": "", "ex": {"en": "Scholars wrote, lectured, and debated vigorously, creating a lively academic environment.", "zh": "学者们积极著书立说、讲学辩论，营造出一种活跃的学术氛围。"}, "key": "vigorously", "aud": false, "hits": []}, "characterise": {"term": "characterise", "zh": "以……为特征", "pos": "动", "src": "", "ex": {"en": "Philosophy in the pre-Qin period was characterised by the emergence of various ancient philosophical schools of thought.", "zh": "先秦时期的哲学以各种古代哲学学派的涌现为特征。"}, "key": "characterise", "aud": false, "hits": []}, "confucianism": {"term": "Confucianism", "zh": "儒家", "pos": "名", "src": "", "ex": {"en": "Confucianism is a school of thought represented by Confucius and Mencius.", "zh": "儒家是由孔子和孟子所代表的学派。"}, "key": "confucianism", "aud": true, "hits": []}, "benevolence": {"term": "benevolence", "zh": "仁", "pos": "名", "src": "", "ex": {"en": "The school advocates core values such as benevolence, righteousness, loyalty, empathy, and the Golden Mean.", "zh": "该学派倡导仁、义、忠、恕以及中庸之道等核心价值观。"}, "key": "benevolence", "aud": true, "hits": []}, "the golden mean": {"term": "the Golden Mean", "zh": "中庸之道", "pos": "短语", "src": "", "ex": {"en": "According to Confucius, the \"mean\" does not imply \"compromise\" but rather a \"moderate\" and \"just right\" approach.", "zh": "在孔子看来，\"中庸\"并非\"妥协\"，而是\"恰到好处\"地理解和处理客观事物的方式。"}, "key": "the_golden_mean", "aud": true, "hits": []}, "embrace": {"term": "embrace", "zh": "信奉；接受", "pos": "动", "src": "", "ex": {"en": "Neighbouring countries such as Japan and Vietnam also embrace Confucianism in their national life and culture.", "zh": "日本、越南等邻国也在其国民生活和文化中信奉儒家学说。"}, "key": "embrace", "aud": false, "hits": []}, "daoism": {"term": "Daoism", "zh": "道家；道教", "pos": "名", "src": "", "ex": {"en": "Daoism is a school of thought that draws from the teachings of Laozi and Zhuangzi.", "zh": "道家是源于老子和庄子学说的学派。"}, "key": "daoism", "aud": true, "hits": []}, "conform to": {"term": "conform (to)", "zh": "遵从；遵循", "pos": "动", "src": "", "ex": {"en": "All people should conform to the dao, which is the course and standard of all things.", "zh": "万事万物都应遵循\"道\"，道是万物的法则与标准。"}, "key": "conform_to", "aud": false, "hits": []}, "overindulgence": {"term": "overindulgence", "zh": "过度沉溺", "pos": "名", "src": "", "ex": {"en": "Daoists believe that overindulgence in these pursuits can bring worries and troubles.", "zh": "道家认为，过度沉溺于这些追求会带来忧虑和烦恼。"}, "key": "overindulgence", "aud": false, "hits": []}, "non action": {"term": "non-action", "zh": "无为", "pos": "名", "src": "", "ex": {"en": "Daoism promotes the political principle of \"achieving good governance through non-action\".", "zh": "道家提倡\"无为而治\"的政治理念。"}, "key": "non_action", "aud": true, "hits": []}, "mohism": {"term": "Mohism", "zh": "墨家", "pos": "名", "src": "", "ex": {"en": "Mohism, based on the teachings of Mozi, emphasises universal love.", "zh": "墨家以墨子学说为基础，强调兼爱。"}, "key": "mohism", "aud": true, "hits": []}, "universal love": {"term": "universal love", "zh": "兼爱", "pos": "短语", "src": "", "ex": {"en": "This principle encourages people to love others, including their families and people of other states, as they love themselves.", "zh": "这一原则鼓励人们像爱自己一样去爱他人，包括自己的家人和别国的人民。"}, "key": "universal_love", "aud": true, "hits": []}, "reject": {"term": "reject", "zh": "反对；摒弃", "pos": "动", "src": "", "ex": {"en": "In politics and ethics, Mohism advocates honouring virtuous people, rejecting fatalism and aggressive wars.", "zh": "在政治与伦理上，墨家主张尊贤，反对宿命论和侵略战争。"}, "key": "reject", "aud": false, "hits": []}, "legalism": {"term": "Legalism", "zh": "法家", "pos": "名", "src": "", "ex": {"en": "Legalism, with Hanfeizi as one of its important representatives, believes that it is necessary to use strict laws to keep the state in order.", "zh": "法家以韩非子为重要代表，认为必须用严明的法律来维持国家秩序。"}, "key": "legalism", "aud": true, "hits": []}, "reject the other schools of thought and respect only confucianism": {"term": "reject the other schools of thought and respect only Confucianism", "zh": "罢黜百家，独尊儒术", "pos": "动", "src": "", "ex": {"en": "In the Western Han Dynasty, Emperor Wudi adopted Dong Zhongshu's proposal of rejecting the other schools of thought and respecting only Confucianism.", "zh": "西汉时期，汉武帝采纳了董仲舒\"罢黜百家，独尊儒术\"的主张。"}, "key": "reject_the_other_schools_of_thought_and_respect_only_confucianism", "aud": false, "hits": []}, "ideology": {"term": "ideology", "zh": "意识形态；官方思想", "pos": "名", "src": "", "ex": {"en": "Confucianism rose from among many schools of thought to become the official ideology.", "zh": "儒家从诸多学派中脱颖而出，成为官方意识形态。"}, "key": "ideology", "aud": false, "hits": []}, "metaphysics": {"term": "metaphysics", "zh": "玄学；形而上学", "pos": "名", "src": "", "ex": {"en": "Metaphysics in China mainly integrates the thoughts of Confucianism and Daoism.", "zh": "中国的玄学主要融合了儒家和道家的思想。"}, "key": "metaphysics", "aud": false, "hits": []}, "noumenon": {"term": "noumenon", "zh": "本体", "pos": "名", "src": "", "ex": {"en": "To explore the noumenon of the universe was the theme of metaphysics in this period.", "zh": "探索宇宙本体是这一时期玄学的主题。"}, "key": "noumenon", "aud": true, "hits": []}, "apex": {"term": "apex", "zh": "顶点；顶峰", "pos": "名", "src": "", "ex": {"en": "During the Sui and Tang dynasties, Buddhism reached its apex in China.", "zh": "隋唐时期，佛教在中国达到了鼎盛。"}, "key": "apex", "aud": true, "hits": []}, "neo confucianism": {"term": "Neo-Confucianism", "zh": "新儒学（宋明理学）", "pos": "形", "src": "", "ex": {"en": "Neo-Confucianism integrated elements of Confucianism, Daoism, and Buddhism.", "zh": "宋明理学融合了儒、道、佛三家的思想。"}, "key": "neo_confucianism", "aud": false, "hits": []}, "rationalism": {"term": "rationalism", "zh": "天理（理学）", "pos": "名", "src": "", "ex": {"en": "The School of Principle argued that \"rationalism\" is eternal and exists as a spiritual essence prior to the material world.", "zh": "理学派认为\"天理\"是永恒的，是先于物质世界而存在的精神本源。"}, "key": "rationalism", "aud": false, "hits": []}, "subjective consciousness": {"term": "subjective consciousness", "zh": "主观意识", "pos": "名", "src": "", "ex": {"en": "They argued that subjective consciousness was the origin of all things in the world.", "zh": "他们主张主观意识是世界万物的本源。"}, "key": "subjective_consciousness", "aud": false, "hits": []}, "practicality": {"term": "practicality", "zh": "实用；经世致用", "pos": "形", "src": "", "ex": {"en": "The school of application philosophy emphasised the promotion of practicality and the rejection of abstraction.", "zh": "实学派强调倡导实用、反对抽象空谈。"}, "key": "practicality", "aud": false, "hits": []}, "cultivate": {"term": "cultivate", "zh": "培养；修养", "pos": "动", "src": "", "ex": {"en": "Confucianism emphasises the cultivation of virtue and moral disposition.", "zh": "儒家强调修养品德与道德操守。"}, "key": "cultivate", "aud": false, "hits": []}, "the unity of knowledge and action": {"term": "the unity of knowledge and action", "zh": "知行合一", "pos": "名", "src": "", "ex": {"en": "Wang Shouren proposed the concept of the \"unity of knowledge and action\".", "zh": "王守仁提出了\"知行合一\"的思想。"}, "key": "the_unity_of_knowledge_and_action", "aud": false, "hits": []}, "filial piety": {"term": "filial piety", "zh": "孝顺", "pos": "短语", "src": "", "ex": {"en": "The father's kindness and the son's filial piety reflect the harmony of family life.", "zh": "父慈子孝体现了家庭生活的和谐。"}, "key": "filial_piety", "aud": true, "hits": []}, "harmony": {"term": "harmony", "zh": "和谐；和", "pos": "名", "src": "", "ex": {"en": "A consistent theme in ancient Chinese philosophy is the emphasis on harmony between man and nature.", "zh": "中国古代哲学一以贯之的主题，是强调人与自然的和谐。"}, "key": "harmony", "aud": false, "hits": []}, "intuition": {"term": "intuition", "zh": "直觉；顿悟", "pos": "名", "src": "", "ex": {"en": "Philosophical concepts were primarily formed through intuition and deep reflection on life experiences.", "zh": "哲学概念主要通过直觉以及对生活经验的深刻反思而形成。"}, "key": "intuition", "aud": false, "hits": []}, "seated meditation": {"term": "seated meditation", "zh": "坐禅", "pos": "短语", "src": "", "ex": {"en": "Chinese Chan Buddhism emphasises sudden enlightenment and focuses on self-restraint and mindfulness through seated meditation.", "zh": "中国禅宗强调顿悟，主张通过坐禅等修行方式来实现自我克制与静心。"}, "key": "seated_meditation", "aud": true, "hits": []}, "ethics": {"term": "ethics", "zh": "伦理", "pos": "名", "src": "", "ex": {"en": "Ethics refers to a set of principles that govern behaviour within a community or society.", "zh": "伦理是指在一个社群或社会中规范行为的规则体系。"}, "key": "ethics", "aud": false, "hits": []}, "morality": {"term": "morality", "zh": "道德", "pos": "名", "src": "", "ex": {"en": "Morality is an individual's internal principles and values that guide their personal conduct.", "zh": "道德是指导个人行为的内在原则与价值观。"}, "key": "morality", "aud": false, "hits": []}, "the five constant virtues": {"term": "the Five Constant Virtues", "zh": "五常", "pos": "短语", "src": "", "ex": {"en": "The Five Constant Virtues advocate benevolence, righteousness, propriety, wisdom, and fidelity.", "zh": "五常倡导仁、义、礼、智、信。"}, "key": "the_five_constant_virtues", "aud": true, "hits": []}, "collectivism": {"term": "collectivism", "zh": "集体主义", "pos": "名", "src": "", "ex": {"en": "Traditional Chinese culture attaches great importance to collective interests.", "zh": "中国传统文化高度重视集体利益。"}, "key": "collectivism", "aud": false, "hits": []}, "prioritise": {"term": "prioritise", "zh": "以…为先；优先考虑", "pos": "动", "src": "", "ex": {"en": "Traditional Chinese culture prioritises the needs of society, the nation, and the family above those of the individual.", "zh": "中国传统文化把社会、国家和家庭的需要置于个人需要之上。"}, "key": "prioritise", "aud": false, "hits": []}, "self cultivation": {"term": "self-cultivation", "zh": "修身；自我修养", "pos": "名", "src": "", "ex": {"en": "Self-cultivation in moral character is emphasised and considered to be more important than material pursuits.", "zh": "人们重视道德品性的修养，认为它比物质追求更为重要。"}, "key": "self_cultivation", "aud": false, "hits": []}, "diverse": {"term": "diverse", "zh": "多样的", "pos": "形", "src": "", "ex": {"en": "China is a country with a rich diversity of religions.", "zh": "中国是一个宗教非常多元化的国家。"}, "key": "diverse", "aud": false, "hits": []}, "harmoniously": {"term": "harmoniously", "zh": "和谐地", "pos": "副", "src": "", "ex": {"en": "In China, all religions enjoy equal status and coexist harmoniously.", "zh": "在中国，各宗教享有平等地位，和谐共存。"}, "key": "harmoniously", "aud": false, "hits": []}, "tenet": {"term": "tenet", "zh": "信条；教义", "pos": "名", "src": "", "ex": {"en": "Its central tenet is called dao, which represents the ultimate principle and natural order of the universe.", "zh": "其核心教义是\"道\"，\"道\"代表着宇宙的终极法则和自然秩序。"}, "key": "tenet", "aud": false, "hits": []}, "scripture": {"term": "scripture", "zh": "经书；经文", "pos": "名", "src": "", "ex": {"en": "One of its foundational scriptures is Daodejing by Laozi.", "zh": "其一部根本经典是老子的《道德经》。"}, "key": "scripture", "aud": false, "hits": []}, "found": {"term": "found", "zh": "创立；创建", "pos": "动", "src": "", "ex": {"en": "\"Wu Dou Mi Daoism\" was founded by Zhang Daoling in Heming Mountain.", "zh": "张道陵在鹤鸣山创立了\"五斗米道\"。"}, "key": "found", "aud": false, "hits": []}, "revere": {"term": "revere", "zh": "尊崇；崇敬", "pos": "动", "src": "", "ex": {"en": "Daoists revere Laozi as the originator of Daoism.", "zh": "道士尊崇老子为道教的创始人。"}, "key": "revere", "aud": false, "hits": []}, "ascetic": {"term": "ascetic", "zh": "修道者", "pos": "名", "src": "", "ex": {"en": "During the early years of Daoism, most Daoist ascetics lived in huts and even caves in remote mountains.", "zh": "道教创立初期，大多数修道者住在茅屋甚至深山洞穴之中。"}, "key": "ascetic", "aud": false, "hits": []}, "summit": {"term": "summit", "zh": "山顶；峰顶", "pos": "名", "src": "", "ex": {"en": "Daoist temples can be found on mountain summits overlooking the sea.", "zh": "道观可以建在高耸入云、俯视大海的山巅之上。"}, "key": "summit", "aud": false, "hits": []}, "immortal": {"term": "immortal", "zh": "神仙；仙人", "pos": "名", "src": "", "ex": {"en": "The main halls serve as places for people to worship Daoist immortals and perform Daoist rituals.", "zh": "主殿是信徒供奉道教神仙、举行道教法事的地方。"}, "key": "immortal", "aud": false, "hits": []}, "elixir": {"term": "elixir", "zh": "不老药；仙丹", "pos": "名", "src": "", "ex": {"en": "Zhang Daoling began distilling elixirs here in his pursuit of immortality.", "zh": "张道陵在此处炼制不老药，以求长生不老。"}, "key": "elixir", "aud": false, "hits": []}, "enlightenment": {"term": "enlightenment", "zh": "觉悟；正觉", "pos": "名", "src": "", "ex": {"en": "Around the age of 29, he chose to abandon the material world in search of enlightenment.", "zh": "大约二十九岁时，他选择舍弃尘世，寻求觉悟。"}, "key": "enlightenment", "aud": false, "hits": []}, "meditation": {"term": "meditation", "zh": "冥想；禅定", "pos": "名", "src": "", "ex": {"en": "Sakyamuni sat under a bodhi tree and fell into deep meditation.", "zh": "释迦牟尼坐在菩提树下，进入深度禅定。"}, "key": "meditation", "aud": true, "hits": []}, "pagoda": {"term": "pagoda", "zh": "宝塔", "pos": "名", "src": "", "ex": {"en": "Chinese Buddhist architecture includes pagodas, temples, and grottoes.", "zh": "中国的佛教建筑包括宝塔、寺院和石窟。"}, "key": "pagoda", "aud": false, "hits": []}, "grotto": {"term": "grotto", "zh": "石窟", "pos": "名", "src": "", "ex": {"en": "Early Buddhist temples often integrated pagodas into courtyard-style layouts.", "zh": "早期的佛教寺院常将宝塔融入庭院式的布局之中。"}, "key": "grotto", "aud": false, "hits": []}, "altar": {"term": "altar", "zh": "佛坛；祭坛", "pos": "名", "src": "", "ex": {"en": "The Mahavira Hall features a main altar for daily Buddhist ceremonies.", "zh": "大雄宝殿设有主佛坛，用于日常佛教法事。"}, "key": "altar", "aud": false, "hits": []}, "envoy": {"term": "envoy", "zh": "使者", "pos": "名", "src": "", "ex": {"en": "Emperor Ming of the Eastern Han Dynasty sent envoys to ancient India to learn about Buddhism.", "zh": "东汉明帝派遣使者前往古印度学习佛法。"}, "key": "envoy", "aud": false, "hits": []}, "sacred": {"term": "sacred", "zh": "神圣的", "pos": "形", "src": "", "ex": {"en": "Mount Wutai, Mount Emei, Mount Putuo, and Mount Jiuhua are recognised as the Four Sacred Buddhist Mountains.", "zh": "五台山、峨眉山、普陀山和九华山被公认为佛教四大名山。"}, "key": "sacred", "aud": false, "hits": []}, "prophet": {"term": "prophet", "zh": "先知", "pos": "名", "src": "", "ex": {"en": "Islam was founded by the Arab prophet Muhammad.", "zh": "伊斯兰教由阿拉伯先知穆罕默德创立。"}, "key": "prophet", "aud": false, "hits": []}, "submit to": {"term": "submit (to)", "zh": "顺从；臣服", "pos": "动", "src": "", "ex": {"en": "Muslims accept and submit to the will of Allah.", "zh": "穆斯林接受并顺从安拉的意志。"}, "key": "submit_to", "aud": false, "hits": []}, "mosque": {"term": "mosque", "zh": "清真寺", "pos": "名", "src": "", "ex": {"en": "A mosque is typically a high-domed building with sweeping arches and towering minarets.", "zh": "清真寺通常是高耸圆顶的建筑，带有拱券和高耸的宣礼塔。"}, "key": "mosque", "aud": true, "hits": []}, "minaret": {"term": "minaret", "zh": "宣礼塔", "pos": "名", "src": "", "ex": {"en": "Outside, there is usually a minaret from which the faithful are called to pray.", "zh": "寺外通常建有宣礼塔，塔上召唤信众前来礼拜。"}, "key": "minaret", "aud": false, "hits": []}, "convert": {"term": "convert", "zh": "使皈依", "pos": "动", "src": "", "ex": {"en": "Muslim merchants travelling along the Silk Road converted many Chinese in the north.", "zh": "沿丝绸之路往来的穆斯林商贾使北方许多中国人皈依了伊斯兰教。"}, "key": "convert", "aud": false, "hits": []}, "confucius": {"term": "Confucius", "zh": "孔子", "pos": "名", "src": "ch1·u2_s2·u2_s2_p3", "ex": {"en": "〔学科注〕Confucianism（儒家）: a school of thought represented by Confucius and Mencius, rooted in the teachings of Confucius, which serve as guiding codes (准则) for behaviour.", "zh": "〔学科注〕儒家：以孔子和孟子为代表的学派，植根于孔子的学说，这些学说构成人们的行为准则。"}, "key": "confucius", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "mencius": {"term": "Mencius", "zh": "孟子", "pos": "", "src": "ch1·u2_s2·u2_s2_p3", "ex": {"en": "", "zh": ""}, "key": "mencius", "aud": false, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "mencius the philosopher": {"term": "Mencius (the philosopher)", "zh": "孟子", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p3", "ex": {"en": "〔学科注〕Confucianism（儒家）: a school of thought represented by Confucius and Mencius, rooted in the teachings of Confucius, which serve as guiding codes (准则) for behaviour.", "zh": "〔学科注〕儒家：以孔子和孟子为代表的学派，植根于孔子的学说，这些学说构成人们的行为准则。"}, "key": "mencius_the_philosopher", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "maitreya buddha": {"term": "Maitreya Buddha", "zh": "弥勒佛", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p3", "ex": {"en": "The front hall usually houses four statues, known as the Four Heavenly Kings (四大天王), while the statue of the Maitreya Buddha (弥勒佛, also known as the Laughing Buddha) is located at the centre of the hall.", "zh": "前殿通常供奉四尊塑像，即四大天王，而弥勒佛（又称笑佛）的塑像则位于殿的中央。"}, "key": "maitreya_buddha", "aud": true, "hits": []}, "the maitreya buddha": {"term": "the Maitreya Buddha", "zh": "弥勒佛", "pos": "", "src": "ch1·u3_s3·u3_s3_p3", "ex": {"en": "", "zh": ""}, "key": "the_maitreya_buddha", "aud": false, "hits": []}, "muhammad": {"term": "Muhammad", "zh": "穆罕默德", "pos": "名", "src": "ch1·u3_s4·u3_s4_p1", "ex": {"en": "Islam was founded by the Arab prophet Muhammad and was introduced into China in the seventh century.", "zh": "伊斯兰教由阿拉伯先知穆罕默德创立，于7世纪传入中国。对穆斯林而言，唯一的真主是安拉。穆斯林接受并顺从安拉的旨意，相信安拉自古以来通过选定的使者与人类沟通；而正是穆罕默德传达了神启，并确立了社会秩序。"}, "key": "muhammad", "aud": true, "hits": []}, "sakyamuni": {"term": "Sakyamuni", "zh": "释迦牟尼", "pos": "名", "src": "ch1·u3_s2·u3_s2_p9", "ex": {"en": "Followers worship the immortals in a manner similar to how Buddhists worship Sakyamuni (释迦牟尼).", "zh": "信徒礼拜神仙的方式，与佛教徒礼拜释迦牟尼相仿。"}, "key": "sakyamuni", "aud": true, "hits": []}, "the three metaphysical classics": {"term": "the Three Metaphysical Classics", "zh": "三玄", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p12", "ex": {"en": "It is based on the famous classical works of The Book of Changes (also known as Yijing), Laozi, and Zhuangzi, collectively known as the Three Metaphysical Classics (三玄).", "zh": "魏晋玄学：中国的玄学主要融汇儒家与道家思想，以《易经》（又称《周易》）、《老子》《庄子》三部经典为依据，合称“三玄”。探究宇宙本体是这一时期玄学的主题，它涉及“有与无”“言与意”“伦理与自然”等重要哲学命题。"}, "key": "the_three_metaphysical_classics", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "the three cardinal guides": {"term": "the Three Cardinal Guides", "zh": "三纲", "pos": "短语", "src": "ch1·u2_s4·u2_s4_p2", "ex": {"en": "In contrast, the concept of the Three Cardinal Guides (三纲), which emphasises hierarchical relationships in feudal society, is widely regarded as outdated and has been largely abandoned.", "zh": "与之相对，“三纲”强调封建社会的等级关系，如今人们普遍视其为过时，大多已弃之不用。"}, "key": "the_three_cardinal_guides", "aud": true, "hits": []}, "study of confucian classics during the han dynasty": {"term": "Study of Confucian Classics During the Han Dynasty", "zh": "两汉经学", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p10", "ex": {"en": "两汉经学 Study of Confucian Classics During the Han Dynasty After the fall of the Qin Dynasty, it became clear that harsh laws alone could not sustain effective governance.", "zh": "两汉经学：秦朝灭亡后，人们认识到仅靠严刑峻法无法维持有效治理。西汉时期，汉武帝采纳董仲舒“罢黜百家，独尊儒术”的主张，儒家遂从众多学派中脱颖而出，成为官方意识形态。"}, "key": "study_of_confucian_classics_during_the_han_dynasty", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "chinese philosophy": {"term": "Chinese philosophy", "zh": "中国哲学", "pos": "短语", "src": "ch1·u2_s1·u2_s1_p1", "ex": {"en": "Chinese philosophy is the collective designation (总称) for various schools of thought.", "zh": "中国哲学是对各种思想学派的总称。"}, "key": "chinese_philosophy", "aud": true, "hits": []}, "fidelity": {"term": "fidelity", "zh": "信", "pos": "名", "src": "ch1·u2_s4·u2_s4_p2", "ex": {"en": "The Five Constant Virtues (五常), which advocate benevolence (仁), righteousness (义), propriety (礼), wisdom (智), and fidelity (信), reflect the high moral standards and ethical wisdom of the Chinese people, offering values of lasting significance.", "zh": "“五常”倡导仁、义、礼、智、信，体现了中华民族崇高的道德标准和伦理智慧，具有持久价值。"}, "key": "fidelity", "aud": true, "hits": []}, "confucian classics": {"term": "Confucian Classics", "zh": "儒家经典", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p10", "ex": {"en": "两汉经学 Study of Confucian Classics During the Han Dynasty After the fall of the Qin Dynasty, it became clear that harsh laws alone could not sustain effective governance.", "zh": "两汉经学：秦朝灭亡后，人们认识到仅靠严刑峻法无法维持有效治理。西汉时期，汉武帝采纳董仲舒“罢黜百家，独尊儒术”的主张，儒家遂从众多学派中脱颖而出，成为官方意识形态。"}, "key": "confucian_classics", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "philosophy in the pre qin period": {"term": "Philosophy in the Pre-Qin Period", "zh": "先秦子学", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p2", "ex": {"en": "先秦子学 Philosophy in the Pre-Qin Period Philosophy in the pre-Qin period was characterised by the emergence of various ancient philosophical schools of thought.", "zh": "先秦子学：先秦时期的哲学以众多古代哲学学派的涌现为特征，其中最具影响力的有儒家、道家、墨家和法家。"}, "key": "philosophy_in_the_pre_qin_period", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "the study of classics in earlier script forms": {"term": "the study of classics in earlier script forms", "zh": "古文经学", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p11", "ex": {"en": "Two interpretive approaches emerged: the study of Confucian classics in the official script of the Han Dynasty (今文经学), which emphasised political relevance, and the study of classics in earlier script forms (古文经学), which focused on textual analysis.", "zh": "这一转变的一个重要特征，是对儒家经典的研究。学者们以先秦儒家典籍为依据，通过注释阐发自己的见解，逐渐形成两种诠释取向：一是今文经学，注重现实政治意义；二是古文经学，侧重文本考据。西汉推崇前者，东汉则兴起后者。"}, "key": "the_study_of_classics_in_earlier_script_forms", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "the four sacred buddhist mountains": {"term": "the Four Sacred Buddhist Mountains", "zh": "四大佛教名山", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p7", "ex": {"en": "佛教名山 Buddhist Mountains Among the many Buddhist mountains in China, Mount Wutai, Mount Emei, Mount Putuo, and Mount Jiuhua are recognised as the Four Sacred Buddhist Mountains.", "zh": "佛教名山：在中国众多佛教名山中，五台山、峨眉山、普陀山和九华山被公认为四大佛教名山。"}, "key": "the_four_sacred_buddhist_mountains", "aud": true, "hits": []}, "fatalism": {"term": "fatalism", "zh": "宿命论", "pos": "名", "src": "ch1·u2_s2·u2_s2_p8", "ex": {"en": "In politics and ethics, Mohism advocates honouring virtuous people, rejecting fatalism (宿命论) and aggressive wars, and promoting thriftiness (节俭) and simple funerals.", "zh": "在政治与伦理方面，墨家提倡尚贤，反对宿命论和侵略战争，主张节俭和薄葬。"}, "key": "fatalism", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "equilibrium": {"term": "Equilibrium", "zh": "平衡", "pos": "名", "src": "ch1·u2_s4·u2_s4_p3", "ex": {"en": "Seeking Harmony and Maintaining Equilibrium（平衡） — To the Chinese people, \"harmony\" is a fundamental concept.", "zh": "尚和求平衡——对中国人而言，“和”是一个基本观念。"}, "key": "equilibrium", "aud": true, "hits": []}, "the school of mind": {"term": "the School of Mind", "zh": "心学", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p15", "ex": {"en": "Neo-Confucianism has two main schools: the School of Principle (理学) and the School of Mind (心学).", "zh": "宋明理学有两大主要流派：理学和心学。理学以周敦颐、程颢、程颐和朱熹为代表，他们认为“理”是永恒的，是先于物质世界而存在的精神实体，宇宙万物皆由“理”派生。心学以陆九渊和王守仁为代表，主张“心外无物，心外无理”，认为主观意识是世间万物的本源。"}, "key": "the_school_of_mind", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "loyalty": {"term": "loyalty", "zh": "忠", "pos": "名", "src": "ch1·u2_s2·u2_s2_p4", "ex": {"en": "The school advocates core values such as benevolence (仁), righteousness (义), loyalty (忠), empathy (恕), and the Golden Mean.", "zh": "儒家是以孔子和孟子为代表的学派，植根于孔子的学说，这些学说构成人们的行为准则。该学派倡导仁、义、忠、恕与中庸等核心价值，重视人与人之间的伦理关系，强调家庭与社会秩序的重要性。例如，子女应当孝敬并照料父母，年幼者应敬重年长者，晚辈应遵从长辈，处于从属地位的人应尽好自己的职责。儒家影响根深蒂固，常被视为中国传统生活与文化的核心。儒家思想并不局限于中国，日本、越南等邻国也在本国生活与文化中信奉儒家。"}, "key": "loyalty", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "empathy": {"term": "empathy", "zh": "恕", "pos": "名", "src": "ch1·u2_s2·u2_s2_p4", "ex": {"en": "The school advocates core values such as benevolence (仁), righteousness (义), loyalty (忠), empathy (恕), and the Golden Mean.", "zh": "儒家是以孔子和孟子为代表的学派，植根于孔子的学说，这些学说构成人们的行为准则。该学派倡导仁、义、忠、恕与中庸等核心价值，重视人与人之间的伦理关系，强调家庭与社会秩序的重要性。例如，子女应当孝敬并照料父母，年幼者应敬重年长者，晚辈应遵从长辈，处于从属地位的人应尽好自己的职责。儒家影响根深蒂固，常被视为中国传统生活与文化的核心。儒家思想并不局限于中国，日本、越南等邻国也在本国生活与文化中信奉儒家。"}, "key": "empathy", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "the wisdom": {"term": "the wisdom", "zh": "智", "pos": "", "src": "ch1·u2_s2·u2_s2_p13", "ex": {"en": "", "zh": ""}, "key": "the_wisdom", "aud": false, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "wisdom": {"term": "wisdom", "zh": "智", "pos": "名", "src": "ch1·u2_s2·u2_s2_p13", "ex": {"en": "The Buddhist philosophy became integrated into the wisdom of Chinese philosophy.", "zh": "隋唐佛学：隋唐时期，佛教在中国达到鼎盛。佛教哲学融入中国哲学的智慧，主要探讨主观与客观的关系。佛教学者通过分析精神现象与人的理性，以求洞察宇宙与人生。"}, "key": "wisdom", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "the noumenon": {"term": "the noumenon", "zh": "本体", "pos": "", "src": "ch1·u2_s2·u2_s2_p12", "ex": {"en": "", "zh": ""}, "key": "the_noumenon", "aud": false, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "the school of principle": {"term": "the School of Principle", "zh": "理学", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p15", "ex": {"en": "Neo-Confucianism has two main schools: the School of Principle (理学) and the School of Mind (心学).", "zh": "宋明理学有两大主要流派：理学和心学。理学以周敦颐、程颢、程颐和朱熹为代表，他们认为“理”是永恒的，是先于物质世界而存在的精神实体，宇宙万物皆由“理”派生。心学以陆九渊和王守仁为代表，主张“心外无物，心外无理”，认为主观意识是世间万物的本源。"}, "key": "the_school_of_principle", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "unity of knowledge and action": {"term": "unity of knowledge and action", "zh": "知行合一", "pos": "短语", "src": "ch1·u2_s3·u2_s3_p3", "ex": {"en": "For example, Wang Shouren proposed the concept of the \"unity of knowledge and action (知行合一)\", arguing that knowledge serves as the guiding principle for practice, and practice is the realisation of knowledge in action.", "zh": "重行（知行合一）——中国古代哲学家探讨的最重要问题之一，是知与行的关系。例如，王守仁提出“知行合一”的主张，认为知是行的指引，行是知在行动中的落实。尽管各家对知与行关系的具体理解不尽相同，但都一致强调通过实际行动把知与行结合起来。【图注：王守仁】"}, "key": "unity_of_knowledge_and_action", "aud": true, "hits": []}, "rejecting the other schools of thought and respecting only confucianism": {"term": "rejecting the other schools of thought and respecting only Confucianism", "zh": "罢黜百家，独尊儒术", "pos": "短语", "src": "ch1·u2_s2·u2_s2_p10", "ex": {"en": "In the Western Han Dynasty, Emperor Wudi adopted Dong Zhongshu's proposal of \"rejecting the other schools of thought and respecting only Confucianism (罢黜百家，独尊儒术)\".", "zh": "两汉经学：秦朝灭亡后，人们认识到仅靠严刑峻法无法维持有效治理。西汉时期，汉武帝采纳董仲舒“罢黜百家，独尊儒术”的主张，儒家遂从众多学派中脱颖而出，成为官方意识形态。"}, "key": "rejecting_the_other_schools_of_thought_and_respecting_only_confucianism", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "stress on harmony": {"term": "Stress on Harmony", "zh": "重和", "pos": "短语", "src": "ch1·u2_s3·u2_s3_p5", "ex": {"en": "Stress on Harmony（重和） — A consistent theme in ancient Chinese philosophy is the emphasis on harmony between man and nature, as well as among people.", "zh": "重和——中国古代哲学中一以贯之的主题，是强调人与自然以及人与人之间的和谐。"}, "key": "stress_on_harmony", "aud": true, "hits": []}, "stress on morality": {"term": "Stress on Morality", "zh": "重德", "pos": "短语", "src": "ch1·u2_s3·u2_s3_p4", "ex": {"en": "Stress on Morality（重德） — Essentially, every school of ancient Chinese philosophy can be considered a kind of moral philosophy.", "zh": "重德——从本质上说，中国古代各个哲学学派都可视为一种道德哲学。"}, "key": "stress_on_morality", "aud": true, "hits": []}, "spiritual life over material life": {"term": "Spiritual Life over Material Life", "zh": "重精神而轻物质", "pos": "短语", "src": "ch1·u2_s4·u2_s4_p5", "ex": {"en": "Spiritual Life over Material Life（重精神而轻物质） — Chinese people deeply value morality in their behaviour.", "zh": "重精神而轻物质——中国人在行为中深切重视道德，强调道德品格的自我修养，并认为它比物质追求更为重要。这体现在孝道、待人以善、尊重他人以及崇尚德行等价值观念中。"}, "key": "spiritual_life_over_material_life", "aud": true, "hits": []}, "stress on practice": {"term": "Stress on Practice", "zh": "重行", "pos": "短语", "src": "ch1·u2_s3·u2_s3_p3", "ex": {"en": "Stress on Practice（重行／知行合一） — One of the most important questions that ancient Chinese philosophers explored was the relationship between knowledge and practice.", "zh": "重行（知行合一）——中国古代哲学家探讨的最重要问题之一，是知与行的关系。例如，王守仁提出“知行合一”的主张，认为知是行的指引，行是知在行动中的落实。尽管各家对知与行关系的具体理解不尽相同，但都一致强调通过实际行动把知与行结合起来。【图注：王守仁】"}, "key": "stress_on_practice", "aud": true, "hits": []}, "collectivism over individualism": {"term": "Collectivism over Individualism", "zh": "重集体而轻个人", "pos": "短语", "src": "ch1·u2_s4·u2_s4_p4", "ex": {"en": "Collectivism over Individualism（重集体而轻个人） — Traditional Chinese culture attaches great importance to collective interests, prioritising the needs of society, the nation, and the family above those of the individual or smaller groups.", "zh": "重集体而轻个人——中国传统文化极为重视集体利益，把社会、国家和家庭的需要置于个人或较小群体之上。"}, "key": "collectivism_over_individualism", "aud": true, "hits": []}, "mount jiuhua": {"term": "Mount Jiuhua", "zh": "九华山", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p7", "ex": {"en": "佛教名山 Buddhist Mountains Among the many Buddhist mountains in China, Mount Wutai, Mount Emei, Mount Putuo, and Mount Jiuhua are recognised as the Four Sacred Buddhist Mountains.", "zh": "佛教名山：在中国众多佛教名山中，五台山、峨眉山、普陀山和九华山被公认为四大佛教名山。"}, "key": "mount_jiuhua", "aud": true, "hits": []}, "mount wutai": {"term": "Mount Wutai", "zh": "五台山", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p7", "ex": {"en": "佛教名山 Buddhist Mountains Among the many Buddhist mountains in China, Mount Wutai, Mount Emei, Mount Putuo, and Mount Jiuhua are recognised as the Four Sacred Buddhist Mountains.", "zh": "佛教名山：在中国众多佛教名山中，五台山、峨眉山、普陀山和九华山被公认为四大佛教名山。"}, "key": "mount_wutai", "aud": true, "hits": []}, "mount emei": {"term": "Mount Emei", "zh": "峨眉山", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p7", "ex": {"en": "佛教名山 Buddhist Mountains Among the many Buddhist mountains in China, Mount Wutai, Mount Emei, Mount Putuo, and Mount Jiuhua are recognised as the Four Sacred Buddhist Mountains.", "zh": "佛教名山：在中国众多佛教名山中，五台山、峨眉山、普陀山和九华山被公认为四大佛教名山。"}, "key": "mount_emei", "aud": true, "hits": []}, "mount putuo": {"term": "Mount Putuo", "zh": "普陀山", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p7", "ex": {"en": "佛教名山 Buddhist Mountains Among the many Buddhist mountains in China, Mount Wutai, Mount Emei, Mount Putuo, and Mount Jiuhua are recognised as the Four Sacred Buddhist Mountains.", "zh": "佛教名山：在中国众多佛教名山中，五台山、峨眉山、普陀山和九华山被公认为四大佛教名山。"}, "key": "mount_putuo", "aud": true, "hits": []}, "dragon tiger mountain": {"term": "Dragon Tiger Mountain", "zh": "龙虎山", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p12", "ex": {"en": "龙虎山 Dragon Tiger Mountain It is believed that Dragon Tiger Mountain is one of the birthplaces of Daoism and is recognised as one of the most sacred mountains in Daoism.", "zh": "龙虎山：一般认为，龙虎山是道教的发祥地之一，也是道教最神圣的名山之一。"}, "key": "dragon_tiger_mountain", "aud": true, "hits": []}, "islam": {"term": "Islam", "zh": "伊斯兰教", "pos": "名", "src": "ch1·u3_s1·u3_s1_p1", "ex": {"en": "There are indigenous Daoist beliefs as well as religions of foreign origin, such as Buddhism and Islam.", "zh": "中国是一个宗教丰富多样的国家，既有本土的道教信仰，也有佛教、伊斯兰教等外来宗教。在中国，各种宗教地位平等、和谐共存，历史上没有宗教冲突。信教者与不信教者彼此尊重，和睦相处。"}, "key": "islam", "aud": true, "hits": []}, "buddhism": {"term": "Buddhism", "zh": "佛教", "pos": "名", "src": "ch1·u1_s0·u1_s0_p1", "ex": {"en": "Culturally, indigenous (本土的) traditions, such as Confucianism and Daoism, along with the religions of foreign origin, such as Buddhism, have profoundly influenced the philosophy, literature, and arts of the Chinese people over the centuries.", "zh": "从文化上看，儒家、道家等本土传统，连同佛教等外来宗教，数百年来深刻影响了中国人民的哲学、文学与艺术。"}, "key": "buddhism", "aud": true, "hits": []}, "eight immortals": {"term": "Eight Immortals", "zh": "八仙", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "Many scenic mountainous locations and buildings have Daoist names, such as the Immortal Bridge (仙人桥), the Incense Burner Peak (香炉峰), and the Temple of the Eight Immortals (八仙庵).", "zh": "许多风景山岳与建筑都有道教色彩的名称，如仙人桥、香炉峰、八仙庵等。"}, "key": "eight_immortals", "aud": true, "hits": []}, "the eight immortals": {"term": "the Eight Immortals", "zh": "八仙", "pos": "", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "", "zh": ""}, "key": "the_eight_immortals", "aud": false, "hits": []}, "the eighteen arhats": {"term": "The Eighteen Arhats", "zh": "十八罗汉", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p5", "ex": {"en": "The Eighteen Arhats (十八罗汉) stand against the east and west walls of the hall.", "zh": "大雄宝殿供奉释迦牟尼及其他佛像，设有主供坛，供日常佛事与诵经之用。供坛下方摆放着一排排蒲团，另有钟、鼓和木鱼。大殿东西两壁立有十八罗汉像，据说他们各有神通。"}, "key": "the_eighteen_arhats", "aud": true, "hits": []}, "the four heavenly kings": {"term": "the Four Heavenly Kings", "zh": "四大天王", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p3", "ex": {"en": "The front hall usually houses four statues, known as the Four Heavenly Kings (四大天王), while the statue of the Maitreya Buddha (弥勒佛, also known as the Laughing Buddha) is located at the centre of the hall.", "zh": "前殿通常供奉四尊塑像，即四大天王，而弥勒佛（又称笑佛）的塑像则位于殿的中央。"}, "key": "the_four_heavenly_kings", "aud": true, "hits": []}, "allah": {"term": "Allah", "zh": "安拉", "pos": "名", "src": "ch1·u3_s4·u3_s4_p1", "ex": {"en": "For Muslims, there is only one God, Allah (安拉).", "zh": "伊斯兰教由阿拉伯先知穆罕默德创立，于7世纪传入中国。对穆斯林而言，唯一的真主是安拉。穆斯林接受并顺从安拉的旨意，相信安拉自古以来通过选定的使者与人类沟通；而正是穆罕默德传达了神启，并确立了社会秩序。"}, "key": "allah", "aud": true, "hits": []}, "grotto heaven": {"term": "grotto heaven", "zh": "洞天", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "Today, Daoist buildings can be found on mountain summits (顶) overlooking the sea, in garden- or park-like designs, or in the \"grotto heaven (洞天)\" style.", "zh": "如今，道观建筑或立于俯瞰大海的山巅，或呈园林、公园式格局，或取“洞天”之式。"}, "key": "grotto_heaven", "aud": true, "hits": []}, "chinese chan buddhism": {"term": "Chinese Chan Buddhism", "zh": "禅宗", "pos": "短语", "src": "ch1·u2_s3·u2_s3_p7", "ex": {"en": "Chinese Chan Buddhism (禅宗), which integrates Buddhist teachings with traditional Chinese philosophy, emphasises sudden enlightenment (顿悟) and focuses on self-restraint and mindfulness through practices such as seated meditation (坐禅) and reciting Buddhist scriptures (经文).", "zh": "中国的禅宗将佛教教义与中国传统哲学相融合，强调顿悟，注重通过坐禅、诵经等修行方式来自我约束、保持正念。"}, "key": "chinese_chan_buddhism", "aud": true, "hits": []}, "bodhi tree": {"term": "bodhi tree", "zh": "菩提树", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p1", "ex": {"en": "Sakyamuni sat under a bodhi tree (菩提树) and fell into deep meditation (冥想).", "zh": "佛教起源于公元前5世纪的古印度。相传释迦牟尼是佛教的创始人。据说他本是一位王子，年少时目睹许多人因贫困、痛苦、疾病和死亡而受苦。约29岁时，他选择舍弃尘世，寻求觉悟。释迦牟尼在菩提树下进入深度冥想，最终觉悟成佛。"}, "key": "bodhi_tree", "aud": true, "hits": []}, "sudden enlightenment": {"term": "sudden enlightenment", "zh": "顿悟", "pos": "短语", "src": "ch1·u2_s3·u2_s3_p7", "ex": {"en": "Chinese Chan Buddhism (禅宗), which integrates Buddhist teachings with traditional Chinese philosophy, emphasises sudden enlightenment (顿悟) and focuses on self-restraint and mindfulness through practices such as seated meditation (坐禅) and reciting Buddhist scriptures (经文).", "zh": "中国的禅宗将佛教教义与中国传统哲学相融合，强调顿悟，注重通过坐禅、诵经等修行方式来自我约束、保持正念。"}, "key": "sudden_enlightenment", "aud": true, "hits": []}, "central axis": {"term": "central axis", "zh": "中轴线", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p9", "ex": {"en": "The main halls usually stand along the central axis (中轴线), serving as places for people to worship Daoist immortals and perform Daoist rituals and ceremonies.", "zh": "主殿通常沿中轴线排列，是人们礼拜道教神仙、举行道教科仪与法事的场所。"}, "key": "central_axis", "aud": true, "hits": []}, "the central axis": {"term": "the central axis", "zh": "中轴线", "pos": "", "src": "ch1·u3_s2·u3_s2_p9", "ex": {"en": "", "zh": ""}, "key": "the_central_axis", "aud": false, "hits": []}, "the immortal bridge": {"term": "the Immortal Bridge", "zh": "仙人桥", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "Many scenic mountainous locations and buildings have Daoist names, such as the Immortal Bridge (仙人桥), the Incense Burner Peak (香炉峰), and the Temple of the Eight Immortals (八仙庵).", "zh": "许多风景山岳与建筑都有道教色彩的名称，如仙人桥、香炉峰、八仙庵等。"}, "key": "the_immortal_bridge", "aud": true, "hits": []}, "the temple of the eight immortals": {"term": "the Temple of the Eight Immortals", "zh": "八仙庵", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "Many scenic mountainous locations and buildings have Daoist names, such as the Immortal Bridge (仙人桥), the Incense Burner Peak (香炉峰), and the Temple of the Eight Immortals (八仙庵).", "zh": "许多风景山岳与建筑都有道教色彩的名称，如仙人桥、香炉峰、八仙庵等。"}, "key": "the_temple_of_the_eight_immortals", "aud": true, "hits": []}, "pagodas": {"term": "pagodas", "zh": "塔", "pos": "名", "src": "ch1·u3_s3·u3_s3_p3", "ex": {"en": "佛教寺院 Buddhist Temples Chinese Buddhist architecture includes pagodas (塔), temples, and grottoes (石窟).", "zh": "佛教寺院：中国佛教建筑包括塔、寺院和石窟。"}, "key": "pagodas", "aud": true, "hits": []}, "the mahavira hall": {"term": "The Mahavira Hall", "zh": "大雄宝殿", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p5", "ex": {"en": "The Mahavira Hall (大雄宝殿) is dedicated to the statue of Sakyamuni and other Buddhas.", "zh": "大雄宝殿供奉释迦牟尼及其他佛像，设有主供坛，供日常佛事与诵经之用。供坛下方摆放着一排排蒲团，另有钟、鼓和木鱼。大殿东西两壁立有十八罗汉像，据说他们各有神通。"}, "key": "the_mahavira_hall", "aud": true, "hits": []}, "minarets": {"term": "minarets", "zh": "宣礼塔", "pos": "名", "src": "ch1·u3_s4·u3_s4_p2", "ex": {"en": "清真寺 Mosques A mosque (清真寺) is typically a high-domed building with sweeping arches, flowing arabesques (阿拉伯式花饰) and towering minarets (宣礼塔).", "zh": "清真寺：清真寺通常是带有高耸穹顶的建筑，拥有舒展的拱门、流畅的阿拉伯式花饰和高耸的宣礼塔。"}, "key": "minarets", "aud": true, "hits": []}, "the qibla wall": {"term": "the qibla wall", "zh": "朝拜墙", "pos": "", "src": "ch1·u3_s4·u3_s4_p3", "ex": {"en": "", "zh": ""}, "key": "the_qibla_wall", "aud": false, "hits": []}, "qibla wall": {"term": "qibla wall", "zh": "朝拜墙", "pos": "短语", "src": "ch1·u3_s4·u3_s4_p3", "ex": {"en": "Inside, a mihrab or prayer niche (壁龛), symbolising the place where the prophet led prayers, is set into the middle of the qibla wall (朝拜墙) to indicate the direction of Mecca.", "zh": "殿内，象征先知领拜之处的一座壁龛（米哈拉布）嵌于朝拜墙中部，用以指示麦加的方向。"}, "key": "qibla_wall", "aud": true, "hits": []}, "mosques": {"term": "Mosques", "zh": "清真寺", "pos": "", "src": "ch1·u3_s4·u3_s4_p2", "ex": {"en": "", "zh": ""}, "key": "mosques", "aud": false, "hits": []}, "the white horse temple": {"term": "The White Horse Temple", "zh": "白马寺", "pos": "短语", "src": "ch1·u3_s3·u3_s3_p6", "ex": {"en": "The White Horse Temple, located to the east of Luoyang, Henan Province, was the first officially built Buddhist temple in China during the Eastern Han Dynasty.", "zh": "白马寺位于河南省洛阳以东，是东汉时期中国第一座官建的佛寺。据史书记载，东汉明帝派遣使者前往古印度了解佛教。使者带着由白马驮载的佛经和佛像回到当时中国的都城洛阳，寺院因此白马而得名。"}, "key": "the_white_horse_temple", "aud": true, "hits": []}, "grottoes": {"term": "grottoes", "zh": "石窟", "pos": "名", "src": "ch1·u3_s3·u3_s3_p3", "ex": {"en": "佛教寺院 Buddhist Temples Chinese Buddhist architecture includes pagodas (塔), temples, and grottoes (石窟).", "zh": "佛教寺院：中国佛教建筑包括塔、寺院和石窟。"}, "key": "grottoes", "aud": true, "hits": []}, "dongguan grand mosque in xining": {"term": "Dongguan Grand Mosque in Xining", "zh": "西宁东关清真大寺", "pos": "短语", "src": "ch1·u3_s4·u3_s4_p5", "ex": {"en": "Most of China's Muslims live in Xinjiang Uygur Autonomous Region, Ningxia Hui Autonomous Region, Gansu Province, Qinghai Province, Henan Province, and Yunnan Province.【图注：Dongguan Grand Mosque in Xining（西宁东关清真大寺）】", "zh": "中国大多数穆斯林生活在新疆维吾尔自治区、宁夏回族自治区、甘肃、青海、河南和云南等省区。【图注：西宁东关清真大寺】"}, "key": "dongguan_grand_mosque_in_xining", "aud": true, "hits": []}, "daoist temples": {"term": "Daoist temples", "zh": "道观", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p4", "ex": {"en": "Its social position improved, leading to the widespread establishment of Daoist temples across the country.", "zh": "自隋唐至北宋，道教尤受皇室庇护，社会地位提高，道观随之在全国广泛兴建。至明朝，道教逐渐衰落。"}, "key": "daoist_temples", "aud": true, "hits": []}, "the incense burner peak": {"term": "the Incense Burner Peak", "zh": "香炉峰", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "Many scenic mountainous locations and buildings have Daoist names, such as the Immortal Bridge (仙人桥), the Incense Burner Peak (香炉峰), and the Temple of the Eight Immortals (八仙庵).", "zh": "许多风景山岳与建筑都有道教色彩的名称，如仙人桥、香炉峰、八仙庵等。"}, "key": "the_incense_burner_peak", "aud": true, "hits": []}, "elixirs": {"term": "elixirs", "zh": "不老药", "pos": "名", "src": "ch1·u3_s2·u3_s2_p12", "ex": {"en": "According to legend, Zhang Daoling, the founder of Daoism, began distilling elixirs (不老药) here in his pursuit of immortality.", "zh": "相传道教创始人张道陵曾在此炼丹，以求长生。"}, "key": "elixirs", "aud": true, "hits": []}, "envoys": {"term": "envoys", "zh": "使者", "pos": "名", "src": "ch1·u3_s3·u3_s3_p6", "ex": {"en": "According to historical accounts, Emperor Ming of the Eastern Han Dynasty sent envoys (使者) to ancient India to learn about Buddhism.", "zh": "白马寺位于河南省洛阳以东，是东汉时期中国第一座官建的佛寺。据史书记载，东汉明帝派遣使者前往古印度了解佛教。使者带着由白马驮载的佛经和佛像回到当时中国的都城洛阳，寺院因此白马而得名。"}, "key": "envoys", "aud": true, "hits": []}, "ascetics": {"term": "ascetics", "zh": "修道者", "pos": "名", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "During the early years of Daoism, most Daoist ascetics (修道者) lived in huts and even caves in remote mountains.", "zh": "道教创立之初，多数修道者栖身于偏远山中的茅屋甚至洞穴之中。"}, "key": "ascetics", "aud": true, "hits": []}, "ablutions": {"term": "ablutions", "zh": "净礼", "pos": "名", "src": "ch1·u3_s4·u3_s4_p3", "ex": {"en": "Outside, there is usually a minaret from which the faithful are called to pray, along with a place for the ablutions (净礼) required before prayer, typically equipped with running water.", "zh": "殿外通常有一座宣礼塔，用来召唤信众礼拜，还有一处供礼拜前净礼的地方，一般配备流水设施。"}, "key": "ablutions", "aud": true, "hits": []}, "the ablutions": {"term": "the ablutions", "zh": "净礼", "pos": "", "src": "ch1·u3_s4·u3_s4_p3", "ex": {"en": "", "zh": ""}, "key": "the_ablutions", "aud": false, "hits": []}, "codes": {"term": "codes", "zh": "准则", "pos": "名", "src": "ch1·u2_s2·u2_s2_p3", "ex": {"en": "〔学科注〕Confucianism（儒家）: a school of thought represented by Confucius and Mencius, rooted in the teachings of Confucius, which serve as guiding codes (准则) for behaviour.", "zh": "〔学科注〕儒家：以孔子和孟子为代表的学派，植根于孔子的学说，这些学说构成人们的行为准则。"}, "key": "codes", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "mountain gates": {"term": "mountain gates", "zh": "山门", "pos": "短语", "src": "ch1·u3_s2·u3_s2_p8", "ex": {"en": "In front of Daoist temples, there are typically mountain gates (山门) and fangan (幡杆) — tall poles used to hang long, narrow flags vertically.", "zh": "道观前方通常设有山门与幡杆——用以竖挂狭长旗帜的高杆。"}, "key": "mountain_gates", "aud": true, "hits": []}, "designation": {"term": "designation", "zh": "总称", "pos": "名", "src": "ch1·u2_s1·u2_s1_p1", "ex": {"en": "Chinese philosophy is the collective designation (总称) for various schools of thought.", "zh": "中国哲学是对各种思想学派的总称。"}, "key": "designation", "aud": true, "hits": []}, "scriptures": {"term": "scriptures", "zh": "经文", "pos": "名", "src": "ch1·u2_s3·u2_s3_p7", "ex": {"en": "Chinese Chan Buddhism (禅宗), which integrates Buddhist teachings with traditional Chinese philosophy, emphasises sudden enlightenment (顿悟) and focuses on self-restraint and mindfulness through practices such as seated meditation (坐禅) and reciting Buddhist scriptures (经文).", "zh": "中国的禅宗将佛教教义与中国传统哲学相融合，强调顿悟，注重通过坐禅、诵经等修行方式来自我约束、保持正念。"}, "key": "scriptures", "aud": true, "hits": []}, "thriftiness": {"term": "thriftiness", "zh": "节俭", "pos": "名", "src": "ch1·u2_s2·u2_s2_p8", "ex": {"en": "In politics and ethics, Mohism advocates honouring virtuous people, rejecting fatalism (宿命论) and aggressive wars, and promoting thriftiness (节俭) and simple funerals.", "zh": "在政治与伦理方面，墨家提倡尚贤，反对宿命论和侵略战争，主张节俭和薄葬。"}, "key": "thriftiness", "aud": true, "hits": [{"set": "CET6 2014·12·S1", "map": "乡村生活理想（儒家与道家）", "cn": "反映在艺术和文学中的乡村生活理想是中国文明的重要特征。", "en": "The ideal of rural life reflected in art and literature is an important feature of Chinese civilization.", "tip": "断句:单分句;核心=①;话题:长定语前置→主语(The ideal of rural life);修饰后置(reflected in art and literature);补主语;文化:中国文明→Chinese civilization(S1 官方行文)", "from": "锚定段"}, {"set": "CET6 2025·12·S3", "map": "节俭", "cn": "节俭 (frugality) 是中华民族的传统美德。", "en": "Frugality is a traditional virtue of the Chinese nation.", "tip": "断句:单分句;核心=①;话题:补主语(→Frugality);文化:节俭→frugality(原卷括注，同源优先)|thriftiness(教材术语库 Ch1，异译)；中华民族→S1 the Chinese nation；传统美德→traditional virtues(S3)", "from": "锚定段"}]}, "cushions": {"term": "cushions", "zh": "蒲团", "pos": "名", "src": "ch1·u3_s3·u3_s3_p5", "ex": {"en": "Rows of cotton cushions (蒲团) are placed below the altar, accompanied by a bell, a drum, and a muyu.", "zh": "大雄宝殿供奉释迦牟尼及其他佛像，设有主供坛，供日常佛事与诵经之用。供坛下方摆放着一排排蒲团，另有钟、鼓和木鱼。大殿东西两壁立有十八罗汉像，据说他们各有神通。"}, "key": "cushions", "aud": true, "hits": []}, "summits": {"term": "summits", "zh": "顶", "pos": "名", "src": "ch1·u3_s2·u3_s2_p6", "ex": {"en": "Today, Daoist buildings can be found on mountain summits (顶) overlooking the sea, in garden- or park-like designs, or in the \"grotto heaven (洞天)\" style.", "zh": "如今，道观建筑或立于俯瞰大海的山巅，或呈园林、公园式格局，或取“洞天”之式。"}, "key": "summits", "aud": true, "hits": []}, "arabesques": {"term": "arabesques", "zh": "阿拉伯式花饰", "pos": "名", "src": "ch1·u3_s4·u3_s4_p2", "ex": {"en": "清真寺 Mosques A mosque (清真寺) is typically a high-domed building with sweeping arches, flowing arabesques (阿拉伯式花饰) and towering minarets (宣礼塔).", "zh": "清真寺：清真寺通常是带有高耸穹顶的建筑，拥有舒展的拱门、流畅的阿拉伯式花饰和高耸的宣礼塔。"}, "key": "arabesques", "aud": true, "hits": []}}, "chunks": [{"en": "silk road", "zh": "丝绸之路", "src": "ch1·u3_s4·u3_s4_p4"}, {"en": "traditional chinese culture", "zh": "中国传统文化", "src": "ch1·u2_s1·u2_s1_p2"}, {"en": "great importance", "zh": "高度重视", "src": "ch1·u2_s4·u2_s4_p4"}, {"en": "thousands of years", "zh": "数千年", "src": "ch1·u1_s0·u1_s0_p1"}, {"en": "thousand years", "zh": "千年", "src": "ch1·u2_s1·u2_s1_p2"}], "audio_base": "../词卡音频/gb_f/", "sets": ["CET6 2014·12·S1", "CET6 2025·12·S3"]};